-- 2. Insert default admin user with BCrypted password
-- Password: 'Admin123!' - generated by BCryptPasswordEncoder
INSERT INTO users (clinic_id, email, phone, password_hash, first_name, last_name, role, is_active, is_verified, created_at)
SELECT
    c.id,
    'admin@cliniq.app',
    '+254700000000',
    '$2a$10$N9qo8uLOb7Gm1YMJqGy3TuKBAx0L5u9pgKqJ/hx8JZTgGZ1KxYKIu',
    'Admin',
    'User',
    'SUPER_ADMIN',
    TRUE,
    FALSE,
    NOW()
FROM clinics c
WHERE c.slug = 'demo';

-- 3. Insert a doctor user (with corresponding doctors table entry)
INSERT INTO users (clinic_id, email, phone, password_hash, first_name, last_name, role, is_active, is_verified, created_at)
SELECT
    c.id,
    'doctor@cliniq.app',
    '+254700000001',
    '$2a$10$N9qo8uLOb7Gm1YMJqGy3TuKBAx0L5u9pgKqJ/hx8JZTgGZ1KxYKIu',
    'Dr.',
    'Medical',
    'DOCTOR',
    TRUE,
    FALSE,
    NOW()
FROM clinics c
WHERE c.slug = 'demo';

-- Insert corresponding doctor record
INSERT INTO doctors (clinic_id, user_id, first_name, last_name, specialization, license_number, max_patients_per_day)
SELECT
    c.id,
    u.id,
    'Dr.',
    'Medical',
    'General Practice',
    'LICENSE-001',
    20
FROM clinics c
CROSS JOIN users u
WHERE c.slug = 'demo' AND u.role = 'DOCTOR';

-- 4. Insert sample patients
INSERT INTO patients (clinic_id, user_id, patient_number, first_name, last_name, phone, email, date_of_birth, gender, blood_group, allergies, emergency_contact_name, emergency_contact_phone, insurance_provider, insurance_number, address, notes, tags)
SELECT
    c.id,
    u.id,
    'PAT001',
    'John',
    'Doe',
    '+254700000003',
    'john.doe@example.com',
    '1980-05-15',
    'Male',
    'O+',
    ARRAY[]::TEXT[],
    'Jane Doe',
    '+254700000004',
    'Amana Health',
    'ANH123456',
    'Nairobi, Kenya',
    'New patient registration',
    '{"new"}'
FROM clinics c
CROSS JOIN users u
WHERE c.slug = 'demo' AND u.role = 'SUPER_ADMIN';

-- 5. Insert sample appointment (doctor_id can be NULL since FK is not NOT NULL)
INSERT INTO appointments (clinic_id, patient_id, doctor_id, appointment_date, start_time, end_time, status, queue_number, visit_type, notes, created_at)
SELECT
    c.id,
    p.id,
    NULL,  -- doctor_id left NULL since FK is not NOT NULL
    CURRENT_DATE,
    '09:00:00',
    '10:00:00',
    'SCHEDULED',
    1,
    'Consultation',
    'First consultation - John Doe',
    NOW()
FROM clinics c
JOIN patients p ON p.clinic_id = c.id AND p.patient_number = 'PAT001'
WHERE c.slug = 'demo';

-- End of seed data